parameters.text:
=User's message: {{ $json.body.userMessage }}

Genre: {{ $json.body.manuscriptData.genre }}

Extract the cover design preferences from their message. If they haven't specified details, suggest appropriate defaults for a {{ $json.body.manuscriptData.genre }} book.

Return ONLY the JSON object, nothing else.

parameters.jsCode:
const aiResponse = $input.first().json;
let coverPrefs;

try {
  // Try to parse the AI response
  const responseText = aiResponse.output || aiResponse.text || aiResponse.content[0].text;
  // Remove markdown code blocks if present
  const cleanedText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  coverPrefs = JSON.parse(cleanedText);
} catch (error) {
  // Fallback to defaults
  coverPrefs = {
    mood: "atmospheric, engaging",
    colors: "vibrant, eye-catching",
    elements: "genre-appropriate imagery",
    style: "professional, cinematic"
  };
}

const webhookData = $('Webhook').first().json.body;

return {
  manuscriptId: webhookData.manuscriptId,
  genre: webhookData.manuscriptData.genre,
  manuscriptTitle: webhookData.manuscriptData.title,
  mood: coverPrefs.mood,
  colors: coverPrefs.colors,
  elements: coverPrefs.elements,
  style: coverPrefs.style,
  readyToGenerate: true
};

return {
  success: true,
  message: "Cover generation started",
  response:
    "🎨 Hang on! Let me create some cover designs. This will take a few minutes so I'll let you know when they're done but you'll be able to view them in the Cover Design Panel",
  estimatedTime: "few minutes",
};

